@Override
    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain filterChain) throws ServletException, IOException {

        Authentication authentication = SecurityContextHolder.getContext().getAuthentication();

        if (authentication != null && authentication.getPrincipal() instanceof Jwt jwt) {
            // Extract uid from JWT and set as request attribute
            String userId = jwt.getSubject();
            request.setAttribute(USER_ID_ATTRIBUTE, userId);

            // Extract complete user information
            String username = null;
            if (jwt.hasClaim("name")) {
                username = jwt.getClaim("name").toString();
            }
            String avatar = null;
            if (jwt.hasClaim("avatar")) {
                avatar = jwt.getClaim("avatar").toString();
            }
            String mobile = null;
            if (jwt.hasClaim("phone")) {
                mobile = jwt.getClaim("phone").toString();
            }
            JwtInfoDto jwtInfoDto = new JwtInfoDto(userId, username, avatar, mobile);
            UserInfo userInfo = createOrGetUserFromJwt(jwtInfoDto);

            // Set complete user information as request attribute
            request.setAttribute(USER_INFO_ATTRIBUTE, userInfo);
        }

        // Pass the request to the next filter in the chain
        filterChain.doFilter(request, response);
    }

private void analysisUse1904WindowDate(XSSFReader xssfReader, XlsxReadWorkbookHolder xlsxReadWorkbookHolder)
            throws Exception {
        if (xlsxReadWorkbookHolder.getReadWorkbook().getUse1904windowing() != null) {
            return;
        }
        InputStream workbookXml = xssfReader.getWorkbookData();
        WorkbookDocument ctWorkbook = WorkbookDocument.Factory.parse(workbookXml);
        CTWorkbook wb = ctWorkbook.getWorkbook();
        CTWorkbookPr prefix = wb.getWorkbookPr();
        if (prefix != null && prefix.getDate1904()) {
            xlsxReadWorkbookHolder.getGlobalConfiguration().setUse1904windowing(Boolean.TRUE);
        } else {
            xlsxReadWorkbookHolder.getGlobalConfiguration().setUse1904windowing(Boolean.FALSE);
        }
    }

